"use strict";

const { test } = require("node:test");
const assert = require("node:assert/strict");
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const cli = path.join(__dirname, "wordfreq.js");

function withInput(contents, run) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "wordfreq-test-"));
  const file = path.join(dir, "input.txt");
  fs.writeFileSync(file, contents, "utf8");
  try {
    run(file);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

function invoke(args) {
  return spawnSync(process.execPath, [cli, ...args], {
    encoding: "utf8",
    timeout: 5000,
  });
}

function rows(stdout) {
  return stdout.trimEnd().split("\n").filter(Boolean).map((line) => {
    const tab = line.lastIndexOf("\t");
    assert.notEqual(tab, -1, `expected word<TAB>count row, got ${JSON.stringify(line)}`);
    return [line.slice(0, tab), Number(line.slice(tab + 1))];
  });
}

test("ranks words by descending frequency, then alphabetically; normalizes Unicode case and punctuation", () => {
  withInput("Banana, apple! BANANA; café CAFÉ. 42 42\ncan't co-op", (file) => {
    const result = invoke([file, "20"]);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(rows(result.stdout), [
      ["42", 2],
      ["banana", 2],
      ["café", 2],
      ["apple", 1],
      ["can't", 1],
      ["co-op", 1],
    ]);
  });
});

test("uses a default limit of 10", () => {
  const words = Array.from({ length: 12 }, (_, i) => `word${String(i).padStart(2, "0")}`).join(" ");
  withInput(words, (file) => {
    const result = invoke([file]);
    assert.equal(result.status, 0, result.stderr);
    const output = rows(result.stdout);
    assert.equal(output.length, 10);
    assert.deepEqual(output.map(([word]) => word), [
      "word00", "word01", "word02", "word03", "word04",
      "word05", "word06", "word07", "word08", "word09",
    ]);
  });
});

test("honors an explicit positive limit", () => {
  withInput("zeta beta alpha beta gamma", (file) => {
    const result = invoke([file, "2"]);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(rows(result.stdout), [["beta", 2], ["alpha", 1]]);
  });
});

