  const missing = path.join(os.tmpdir(), `wordfreq-missing-${process.pid}-${Date.now()}.txt`);
  const result = invoke([missing]);
  assert.notEqual(result.status, 0);
  assert.ok(result.stderr.length > 0, "expected an error message on stderr");
});

test("rejects an invalid limit", () => {
