test('reports a missing file as an error', () => {
  const missing = path.join(os.tmpdir(), `wordfreq-no-such-file-${process.pid}-${Date.now()}`);
  const result = invoke([missing]);
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
});
